cd multicode/duckpit/build/onepit/iter8d/v6l/R/ && python3 -I - <<'EOF'
import re,glob
def run(f):
    pas=None;inn=0;src={}
    L=open(f,errors='ignore').read().splitlines()
    for l in L:
        m=re.search(r'pit pass ch=1 t=([\d.]+)',l)
        if m and pas is None: pas=float(m.group(1))
    for l in L:
        m=re.search(r'ledger tag=minute .*? in=([\d.]+) .*?t=([\d.]+) ch=',l)
        if m and float(m.group(2))<=pas:
            inn=float(m.group(1)); src=dict(re.findall(r'src_(\w+)=([\d.]+)',l))
    return pas,inn,src
for d in ('base/nb4_s550[5-8]','base/nbr_s550*','after/nb_s550*','after/nbr_s550*'):
    for f in sorted(glob.glob(d+'.log')):
        p,i,s=run(f)
        top=sorted(((float(v),k) for k,v in s.items()),reverse=True)[:4]
        print(f.split('/')[-1][:-4],round(p/60,1),round(i),[(k,round(v/i*100)) for v,k in top], 'turbo%.0f'%float(s.get('turbo',0)))
EOF
